begin
  if (select count(*) from public.lessons where id in ('c0000000-0000-0000-0000-000000000001'::uuid, 'd8cffb46-8a62-538a-b864-e227a6d8b863'::uuid, 'a17f2f16-1be9-50f2-8e16-2bebfcced33b'::uuid, 'e704760a-f743-5762-9c1a-027b10ca030a'::uuid, '2b6ed342-cc80-5bd9-baf0-b66109624d62'::uuid, '04167753-db83-5163-a91c-9f71dac18ab5'::uuid, '8f6439a9-c6ac-5271-99c8-1f0adc5d7599'::uuid, '2fa5fa38-9641-5dc5-9156-6a3f7fe8035b'::uuid, '3b51b1bf-47f4-5709-96d9-c518d36440e6'::uuid, '22dd7878-4fa8-5e1c-909e-71c70ffd9918'::uuid, '036fc4fb-1bf2-5100-9fd0-6f6a612554a1'::uuid, 'd7cf3059-0d92-5215-8ef4-ad699e317b10'::uuid, '4e003796-1ce0-5a02-8a2d-59a0de38f3dd'::uuid, '2b0e9742-99e1-57e1-a574-67ffb78d2607'::uuid, '78f28f85-dd8b-5e81-8a52-1b2dbce4eb34'::uuid, '4bf48151-be83-5108-bc92-645c0603a1a3'::uuid, '959e879f-a28d-5bed-9c09-16cff91ef456'::uuid, 'd43d6c65-1ce3-5c72-9ecd-cce2ed200fc2'::uuid, '63a4a6d8-1cae-5e0e-90ff-98efcfe8b4c7'::uuid, 'ad0bc1f4-2808-5b24-969d-9da64d4a7a4d'::uuid, 'b369f01f-4a84-57b4-98cb-150d236f4d7f'::uuid, 'd813e9c0-2331-59d8-90f1-cea7e9a61c7d'::uuid, '1c16ceee-5f42-536a-98b4-7dcabaa3be6d'::uuid, '3f440ad8-f057-5898-b773-6aa8816fa8a3'::uuid, 'dbb91fa1-4a97-5c04-99a8-8ac1d508b952'::uuid) and status = 'PUBLISHED') <> 25 then
