  end if;
  for w in select * from jsonb_to_recordset('[{"lemma": "puno", "norm": "puno", "pos": "adverb", "cefr": "A1", "tr": "багато", "vt": "function_word", "forms": {}, "ex": ["Ovdje ima puno ljudi.", "Puno hvala na pomoći!"], "lesson": "c0000000-0000-0000-0000-000000000001", "fix_tr": null, "fix_ex": null, "fix_forms": null}, {"lemma": "tako", "norm": "tako", "pos": "adverb", "cefr": "A1", "tr": "так, таким чином", "vt": "core", "forms": {}, "ex": ["Nemoj tako brzo voziti!"], "lesson": "c0000000-0000-0000-0000-000000000001", "fix_tr": null, "fix_ex": ["Nemoj tako brzo voziti!", "Tako je, imaš pravo."], "fix_forms": null}, {"lemma": "vidjeti", "norm": "vidjeti", "pos": "verb", "cefr": "A1", "tr": "бачити", "vt": "core", "forms": {"past": "vidio", "aspect": "biasp", "present": {"1s": "vidim", "2s": "vidiš", "3s": "vidi"}}, "ex": ["Ne vidim dobro.", "Jesi li vidjela moje ključeve?"], "lesson": "d8cffb46-8a62-538a-b864-e227a6d8b863", "fix_tr": null, "fix_ex": null, "fix_forms": null}, {"lemma": "čuti", "norm": "cuti", "pos": "verb", "cefr": "A1", "tr": "чути", "vt": "core", "forms": {"aspect": "biasp", "present": {"1s": "čujem", "2s": "čuješ", "3s": "čuje"}}, "ex": ["Čuješ li me?", "Ne čujem te dobro, govori glasnije."], "lesson": "d8cffb46-8a62-538a-b864-e227a6d8b863", "fix_tr": null, "fix_ex": null, "fix_forms": null}, {"lemma": "reći", "norm": "reci", "pos": "verb", "cefr": "A1", "tr": "сказати", "vt": "core", "forms": {"past": "rekao", "aspect": "pfv", "present": {"1s": "kažem", "2s": "kažeš", "3s": "kaže"}}, "ex": ["Što si rekao?", "Kako se kaže...?"], "lesson": "a17f2f16-1be9-50f2-8e16-2bebfcced33b", "fix_tr": null, "fix_ex": ["Što si rekao?", "Možete li mi reći gdje je pošta?"], "fix_forms": null}, {"lemma": "ili", "norm": "ili", "pos": "conjunction", "cefr": "A1", "tr": "або; чи", "vt": "function_word", "forms": {}, "ex": ["Kava ili čaj?"], "lesson": "e704760a-f743-5762-9c1a-027b10ca030a", "fix_tr": "або; чи", "fix_ex": ["Kava ili čaj?", "Platit ću karticom ili gotov