kao pravi Hrvat!", "Radim kao konobarica."], "fix_forms": null}, {"lemma": "možda", "norm": "mozda", "pos": "adverb", "cefr": "A1", "tr": "можливо", "vt": "function_word", "forms": {}, "ex": ["Možda ću doći sutra.", "Možda je u pravu."], "lesson": "2fa5fa38-9641-5dc5-9156-6a3f7fe8035b", "fix_tr": null, "fix_ex": null, "fix_forms": null}, {"lemma": "loš", "norm": "los", "pos": "adjective", "cefr": "A1", "tr": "поганий", "vt": "core", "forms": {"f": "loša", "n": "loše", "plural": "loši"}, "ex": ["Danas je loše vrijeme."], "lesson": "3b51b1bf-47f4-5709-96d9-c518d36440e6", "fix_tr": null, "fix_ex": ["Danas je loše vrijeme.", "Osjećam se loše."], "fix_forms": null}, {"lemma": "trebati", "norm": "trebati", "pos": "verb", "cefr": "A1", "tr": "потребувати", "vt": "core", "forms": {"aspect": "ipfv", "present": {"1s": "trebam", "2s": "trebaš", "3s": "treba"}}, "ex": ["Trebam pomoć.", "Što trebate?"], "lesson": "3b51b1bf-47f4-5709-96d9-c518d36440e6", "fix_tr": "потребувати; бути потрібним (treba mi — мені треба)", "fix_ex": null, "fix_forms": null}, {"lemma": "željeti", "norm": "zeljeti", "pos": "verb", "cefr": "A1", "tr": "бажати", "vt": "core", "forms": {"aspect": "ipfv"}, "ex": ["Što biste željeli popiti?"], "lesson": "3b51b1bf-47f4-5709-96d9-c518d36440e6", "fix_tr": "бажати; хотіти", "fix_ex": ["Što biste željeli popiti?", "Želim ti sretan put!"], "fix_forms": null}, {"lemma": "sve", "norm": "sve", "pos": "pronoun", "cefr": "A1", "tr": "все", "vt": "function_word", "forms": {}, "ex": ["Sve je u redu.", "Znam sve o tome."], "lesson": "22dd7878-4fa8-5e1c-909e-71c70ffd9918", "fix_tr": "усе", "fix_ex": null, "fix_forms": null}, {"lemma": "topao", "norm": "topao", "pos": "adjective", "cefr": "A1", "tr": "теплий", "vt": "core", "forms": {"f": "topla", "n": "toplo", "plural": "topli"}, "ex": ["Toplo more i sunčan dan."], "lesson": "036fc4fb-1bf2-5100-9fd0-6f6a612554a1", "fix_tr": null, "fix_ex": ["Danas je topao dan.", "More je toplo u kolovozu."], "fix_forms": null}, {"lemma": "važan", "norm": "vazan", "pos": "adjective", "cefr": "A1", "tr": "важливий", "vt": "core", "forms": {"f": "važna", "n": "važno", "plural": "važni"}, "ex": ["Imam važan sastanak u uredu."], "lesson": "d7cf3059-0d92-5215-8ef4-ad699e317b10", "fix_tr": null, "fix_ex": ["Imam važan sastanak u uredu.", "Obitelj mi je jako važna."], "fix_forms": null}, {"lemma": "roditelj", "norm": "roditelj", "pos": "noun", "cefr": "A1", "tr": "батько/мати", "vt": "core", "forms": {"gender": "m", "plural": "roditelji"}, "ex": ["Svaki roditelj želi najbolje za dijete."], "lesson": "4e003796-1ce0-5a02-8a2d-59a0de38f3dd", "fix_tr": "один із батьків; roditelji — батьки", "fix_ex": ["Svaki roditelj želi najbolje za dijete.", "Moji roditelji žive u Kijevu."], "fix_forms": {"gender": "m", "plural": "roditelji"}}, {"lemma": "sjediti", "norm": "sjediti", "pos": "verb", "cefr": "A1", "tr": "сидіти", "vt": "core", "forms": {"aspect": "ipfv"}, "ex": ["Mogu li sjediti ovdje?"], "lesson": "2b0e9742-99e1-57e1-a574-67ffb78d2607", "fix_tr": null, "fix_ex": ["Mogu li sjediti ovdje?", "Djeca sjede za stolom."], "fix_forms": {"aspect": "ipfv", "present": {"1s": "sjedim", "2s": "sjediš", "3s": "sjedi"}}}, {"lemma": "ako", "norm": "ako", "pos": "conjunction", "cefr": "A1", "tr": "якщо", "vt": "function_word", "forms": {}, "ex": ["Ako želiš, idemo na kavu.", "Ako pada kiša, ostajem kod kuće."], "lesson": "78f28f85-dd8b-5e81-8a52-1b2dbce4eb34", "fix_tr": null, "fix_ex": null, "fix_forms": null}, {"lemma": "čitati", "norm": "citati", "pos": "verb", "cefr": "A1", "tr": "читати", "vt": "core", "forms": {"past": "čitao", "aspect": "ipfv", "present": {"1s": "čitam", "2s": "čitaš", "3s": "čita", "1p": "čitamo", "2p": "čitate", "3p": "čitaju"}}, "ex": ["Volim čitati knjige uvečer."], "lesson": "4bf48151-be83-5108-bc92-645c0603a1a3", "fix_tr": null, "fix_ex": ["Volim čitati knjige uvečer.", "Ujutro čitam vijesti na mobitelu."], "fix_forms": null}, {"lemma": "svaki", "norm": "svaki", "pos": "pronoun", "cefr": "A1", "tr": "кожен", "vt": "function_word", "forms": {"f": "svaka", "n": "svako"}, "ex": ["Svaki dan idem na posao.", "Svaka soba ima balkon."], "lesson": "959e879f-a28d-5bed-9c09-16cff91ef456", "fix_tr": null, "fix_ex": null, "fix_forms": null}, {"lemma": "trčati", "norm": "trcati", "pos": "verb", "cefr": "A1", "tr": "бігати", "vt": "core", "forms": {"past": "trčao", "aspect": "ipfv", "present": {"1s": "trčim", "2s": "trčiš", "3s": "trči", "1p": "trčimo", "2p": "trčite", "3p": "trče"}}, "ex": ["Trčim u parku svako jutro."], "lesson": "959e879f-a28d-5bed-9c09-16cff91ef456", "fix_tr": null, "fix_ex": null, "fix_forms": null}, {"lemma": "gledati", "norm": "gledati", "pos": "verb", "cefr": "A1", "tr": "дивитися", "vt": "core", "forms": {"past": "gledao", "aspect": "ipfv", "present": {"1s": "gledam", "2s": "gledaš", "3s": "gleda", "1p": "gledamo", "2p": "gledate", "3p": "gledaju"}}, "ex": ["Gledam televiziju svake večeri."], "lesson": "d43d6c65-1ce3-5c72-9ecd-cce2ed200fc2", "fix_tr": null, "fix_ex": ["Gledam televiziju svake večeri.", "Djeca gledaju crtiće."], "fix_forms": null}, {"lemma": "jer", "norm": "jer", "pos": "conjunction", "cefr": "A1", "tr": "тому що / бо", "vt": "function_word", "forms": {}, "ex": ["Ne radim jer sam bolestan.", "Idem kući jer je kasno."], "lesson": "63a4a6d8-1cae-5e0e-90ff-98efcfe8b4c7", "fix_tr": "бо; тому що", "fix_ex": null, "fix_forms": null}, {"lemma": "lak", "norm": "lak", "pos": "adjective", "cefr": "A1", "tr": "легкий", "vt": "core", "forms": {"f": "laka", "n": "lako", "plural": "laki"}, "ex": ["Lak test iz hrvatskog."], "lesson": "ad0bc1f4-2808-5b24-969d-9da64d4a7a4d", "fix_tr": null, "fix_ex": ["Ovaj test je lak.", "Hrvatski nije lak, ali je lijep."], "fix_forms": null}, {"lemma": "vrlo", "norm": "vrlo", "pos": "adverb", "cefr": "A1", "tr": "дуже", "vt": "function_word", "forms": {}, "ex": ["Vrlo je lijepo vrijeme.", "Hvala, vrlo ste ljubazni."], "lesson": "ad0bc1f4-2808-5b24-969d-9da64d4a7a4d", "fix_tr": null, "fix_ex": null, "fix_forms": null}, {"lemma": "dom", "norm": "dom", "pos": "noun", "cefr": "A1", "tr": "гуртожиток", "vt": "core", "forms": {"gender": "m"}, "ex": ["Studenti žive u studentskom domu."], "lesson": "b369f01f-4a84-57b4-98cb-150d236f4d7f", "fix_tr": "дім, оселя; заклад (dom za starije — будинок для літніх людей, dom zdravlja — поліклініка, studentski dom — гуртожиток)", "fix_ex": ["Ona radi u domu za starije.", "Studenti žive u studentskom domu."], "fix_forms": {"gender": "m", "plural": "domovi"}}, {"lemma": "razgovarati", "norm": "razgovarati", "pos": "verb", "cefr": "A1", "tr": "розмовляти", "vt": "core", "forms": {"aspect": "ipfv"}, "ex": ["Moramo razgovarati."], "lesson": "d813e9c0-2331-59d8-90f1-cea7e9a61c7d", "fix_tr": null, "fix_ex": ["Moramo razgovarati.", "Na pauzi razgovaram s kolegama."], "fix_forms": {"aspect": "ipfv", "present": {"1s": "razgovaram", "2s": "razgovaraš", "3s": "razgovara"}}}, {"lemma": "slušati", "norm": "slusati", "pos": "verb", "cefr": "A1", "tr": "слухати", "vt": "core", "forms": {"past": "slušao", "aspect": "ipfv", "present": {"1s": "slušam", "2s": "slušaš", "3s": "sluša", "1p": "slušamo", "2p": "slušate", "3p": "slušaju"}}, "ex": ["Slušam glazbu u autu."], "lesson": "1c16ceee-5f42-536a-98b4-7dcabaa3be6d", "fix_tr": null, "fix_ex": ["Slušam glazbu u autu.", "Koju glazbu voliš slušati?"], "fix_forms": null}, {"lemma": "dok", "norm": "dok", "pos": "conjunction", "cefr": "A1", "tr": "поки, доки", "vt": "core", "forms": {}, "ex": ["Čekaj me ovdje dok ne dođem."], "lesson": "3f440ad8-f057-5898-b773-6aa8816fa8a3", "fix_tr": "поки; доки", "fix_ex": ["Čekaj me ovdje dok ne dođem.", "Dok kuham, slušam radio."], "fix_forms": null}, {"lemma": "život", "norm": "zivot", "pos": "noun", "cefr": "A1", "tr": "життя", "vt": "core", "forms": {"gender": "m"}, "ex": ["Život na moru je lijep."], "lesson": "dbb91fa1-4a97-5c04-99a8-8ac1d508b952", "fix_tr": null, "fix_ex": ["Život na moru je lijep.", "Ovdje počinjem novi život."], "fix_forms": {"gender": "m", "plural": "životi"}}]'::jsonb)
      as t(lemma text, norm text, pos text, cefr text, tr text, vt text, forms jsonb, ex jsonb, lesson uuid,
           fix_tr text, fix_ex jsonb, fix_forms jsonb)
  loop
    -- у робочій базі слова вже є (крім svaki, vrlo); у локальній / CI — створюються
    insert into public.lexemes (lemma, normalized, language, part_of_speech, cefr, ukrainian_translation, vocabulary_type,
                                forms, examples, status, source)
    values (w.lemma, w.norm, 'hr', w.pos, w.cefr, w.tr, w.vt, w.forms, w.ex, 'PUBLISHED', 'claude_core_words_20261104')
    on conflict do nothing;
    select * into x from public.lexemes where lower(lemma) = lower(w.lemma);
    if x.id is null or x.status <> 'PUBLISHED' then
      raise exception 'Слово % не опубліковане — перевірте словник', w.lemma;
    end if;
    -- виправлення перекладу / прикладів / форм
    if (w.fix_tr is not null and x.ukrainian_translation is distinct from w.fix_tr)
       or (w.fix_ex is not null and x.examples is distinct from w.fix_ex)
       or (w.fix_forms is not null and x.forms is distinct from w.fix_forms) then
      insert into public.content_versions (entity_type, entity_id, version, payload, change_reason)
      values ('lexeme', x.id,
              coalesce((select max(version) from public.content_versions where entity_type = 'lexeme' and entity_id = x.id), 0) + 1,
              to_jsonb(x), 'core_words_20261104: переклад / приклади / форми — стара версія');
      update public.lexemes set
        ukrainian_translation = coalesce(w.fix_tr, ukrainian_translation),
        examples = coalesce(w.fix_ex, examples),
        forms = coalesce(w.fix_forms, forms),
        version = coalesce(version, 1) + 1
      where id = x.id;
      insert into public.content_reviews (entity_type, entity_id, from_status, to_status, verdict, reviewer_kind, findings, notes)
      values ('lexeme', x.id, x.status, x.status, 'auto_passed', 'ai',
              jsonb_build_array(jsonb_build_object('old_tr', x.ukrainian_translation, 'new_tr', w.fix_tr,
                                                   'old_ex', x.examples, 'new_ex', w.fix_ex)), 'Аудит A0 + A1 2026-11-04: базове слово додано в урок / виправлено переклад чи приклад. Потрібна перевірка носієм.');
      v_fixed := v_fixed + 1;
    end if;
    -- у список слів уроку (після наявних елементів)
    if not exists (select 1 from public.lesson_items where lesson_id = w.lesson and item_type = 'lexeme' and item_id = x.id) then
      select coalesce(max(order_index), 0) + 1 into v_ord from public.lesson_items where lesson_id = w.lesson;
      insert into public.lesson_items (id, lesson_id, item_type, item_id, order_index, required, target_skill)
      values (gen_random_uuid(), w.lesson, 'lexeme', x.id, v_ord, true, 'vocabulary');
      v_items := v_items + 1;
    end if;
  end loop;
  raise notice 'Слова: додано в уроки %, виправлено %', v_items, v_fixed;
end
$words$;

-- ---------------------------------------------------------------- 2. Нові правила граматики
do $newrules$
declare
  r record;
  v_topic uuid;
  v_after int;
  v_new int := 0;
begin
  for r in select * from jsonb_to_recordset('[{"topic": "Rod, množina i posvojne zamjenice", "after": "Множина", "title": "Короткі слова: grad → gradovi", "expl": "Більшість односкладових іменників чоловічого роду в множині отримують -ovi: grad → gradovi, stol → stolovi, sin → sinovi, vlak → vlakovi. Якщо слово закінчується на м’який приголосний (č, ć, š, ž, đ, j, lj, nj), то -evi: muž → muževi, ključ → ključevi, broj → brojevi. «Gradi» чи «stoli» — помилка. Винятки: dan → dani, zub → zubi, konj → konji.", "pattern": "grad → gradovi · stol → stolovi · ključ → ključevi", "ex": [{"hr": "Svi stolovi su zauzeti.", "ua": "Усі столики зайняті."}, {"hr": "Gdje su moji ključevi?", "ua": "Де мої ключі?"}, {"hr": "Vlakovi za Split su puni.", "ua": "Поїзди до Спліта переповнені."}, {"hr": "Moji sinovi idu u školu.", "ua": "Мої сини ходять до школи."}, {"hr": "Ovi brojevi nisu točni.", "ua": "Ці номери неправильні."}]}, {"topic": "Lokativ", "after": "O + місцевий: про кого, про що", "title": "Ruka — u ruci: зміна k, g, h", "expl": "Перед закінченням -i в місцевому (і давальному) відмінку жіночого роду k, g, h змінюються на c, z, s: ruka → u ruci, knjiga → u knjizi, Rijeka → u Rijeci, noga → na nozi. Так само, як в українському «рука — в руці, нога — на нозі». Винятки — деякі слова про людей і тварин: baka → baki, mačka → mački.", "pattern": "ruka → u ruci · knjiga → o knjizi · Rijeka → u Rijeci", "ex": [{"hr": "Živim u Rijeci.", "ua": "Я живу в Рієці."}, {"hr": "Što imaš u ruci?", "ua": "Що в тебе в руці?"}, {"hr": "Čitam o tome u knjizi.", "ua": "Я читаю про це в книжці."}, {"hr": "Na nozi imam flaster.", "ua": "На нозі в мене пластир."}]}, {"topic": "Genitiv: osnove", "after": null, "title": "Od mene, kod nas, o tebi: займенники після прийменників", "expl": "Після прийменників особові займенники мають повні форми. Родовий (після od, do, kod, iz, bez): mene, tebe, njega, nje, nas, vas, njih — kod nas, od tebe, bez njega. Місцевий (після o, u, na, po): meni, tebi, njemu, njoj, nama, vama, njima — o meni, o njoj. Короткі форми (me, te, ga) після прийменника не вживаються.", "pattern": "kod nas · od mene · bez tebe · o njoj", "ex": [{"hr": "Kod nas je danas toplo.", "ua": "У нас сьогодні тепло."}, {"hr": "Ovo je poklon od mene.", "ua": "Це подарунок від мене."}, {"hr": "Ne mogu bez tebe.", "ua": "Я не можу без тебе."}, {"hr": "Što misliš o njemu?", "ua": "Що ти думаєш про нього?"}, {"hr": "Pričamo o tebi.", "ua": "Ми говоримо про тебе."}]}]'::jsonb)
      as t(topic text, after text, title text, expl text, pattern text, ex jsonb)
  loop
    select id into v_topic from public.grammar_topics
     where title_hr = r.topic and cefr in ('A0', 'A1') and status = 'PUBLISHED';
    if v_topic is null then raise exception 'Тему граматики «%» не знайдено', r.topic; end if;
    if exists (select 1 from public.grammar_rules where topic_id = v_topic and title_ua = r.title) then
      continue;
    end if;
    if r.after is null then
      select coalesce(max(order_index), 0) into v_after from public.grammar_rules where topic_id = v_topic;
    else
      select order_index into v_after from public.grammar_rules where topic_id = v_topic and title_ua = r.after;
      if v_after is null then raise exception 'У темі «%» немає правила «%»', r.topic, r.after; end if;
      update public.grammar_rules set order_index = order_index + 1 where topic_id = v_topic and order_index > v_after;
    end if;
    insert into public.grammar_rules (id, topic_id, title_ua, explanation_ua, pattern_hr, examples, order_index)
    values (gen_random_uuid(), v_topic, r.title, r.expl, r.pattern, r.ex, v_after + 1);
    v_new := v_new + 1;
  end loop;
  raise notice 'Нових правил: %', v_new;
end
$newrules$;

-- ---------------------------------------------------------------- 3. Довші пояснення й приклади
do $rules$
declare
  r record;
  g public.grammar_rules%rowtype;
  v_ex jsonb;
  k text;
  a jsonb;
  v_changed int := 0;
begin
  for r in select * from jsonb_to_recordset('[{"topic": "Osobne zamjenice i glagol BITI", "title": "Особові займенники (однина)", "e": "Особові займенники однини: ja (я), ti (ти), on (він), ona (вона), ono (воно). Їх часто пропускають, бо форма дієслова вже показує особу: «Ja sam iz Ukrajine» = «Iz Ukrajine sam». Займенник лишаємо, коли хочемо підкреслити або протиставити: Ja sam Daša, a ti?", "fix": {}, "add": [{"hr": "On je moj brat.", "ua": "Він мій брат."}, {"hr": "Iz Kijeva sam.", "ua": "Я з Києва."}]}, {"topic": "Osobne zamjenice i glagol BITI", "title": "Дієслово BITI (бути) - короткі форми", "e": "Biti («бути») у теперішньому часі має короткі форми: sam, si, je, smo, ste, su. В українській «є» зазвичай пропускаємо, а в хорватській — ні: «Я втомлений» — Umoran sam. Короткі форми не стоять першими в реченні: Ja sam Ana або Ana sam, але не «Sam Ana».", "fix": {"0": {"hr": "Ja sam dobro.", "ua": "У мене все добре."}, "1": {"hr": "Kako si?", "ua": "Як ти?"}}, "add": [{"hr": "Mi smo iz Ukrajine.", "ua": "Ми з України."}, {"hr": "Oni su u Zagrebu.", "ua": "Вони в Загребі."}]}, {"topic": "Glagol imati", "title": "Imam, imaš, ima…", "e": "Imati — «мати». Де українською кажемо «у мене є», хорватською кажуть «я маю»: Imam auto — «У мене є машина». Форми: imam, imaš, ima, imamo, imate, imaju. Те, що маємо, стоїть у знахідному відмінку: Imam sestru.", "fix": {}, "add": [{"hr": "Imamo mali stan.", "ua": "У нас маленька квартира."}, {"hr": "Ana ima dva psa.", "ua": "В Ани два собаки."}]}, {"topic": "Glagol imati", "title": "Nemam, nemaš, nema…", "e": "Заперечення від imati пишемо одним словом: ne + imam = nemam, далі nemaš, nema, nemamo, nemate, nemaju. Те, чого немає, стоїть у родовому відмінку: nemam vremena, nema mlijeka. «Nema» також означає «немає» взагалі: Nema problema.", "fix": {}, "add": [{"hr": "Danas nema autobusa.", "ua": "Сьогодні немає автобуса."}]}, {"topic": "Glagol imati", "title": "Питання: дієслово + li", "e": "Питання «так / ні» з imati: li ставимо одразу після дієслова — Imate li…? Imaš li…? Ima li…? Відповідь — коротко тим самим дієсловом: Imam / Nemam (або Ima / Nema). Так само з іншими дієсловами: Govorite li…? Znaš li…?", "fix": {}, "add": [{"hr": "Imate li sobu za dvije osobe?", "ua": "У вас є кімната на двох?"}]}, {"topic": "Pokazne zamjenice: ovaj, taj, onaj", "title": "Ovaj / ova / ovo — біля мене", "e": "Ovaj (ч. р.), ova (ж. р.), ovo (с. р.) — «цей, ця, це» про те, що поруч із тим, хто говорить: ovaj kruh, який я тримаю. Займенник узгоджується з іменником за родом. Ovo без іменника означає «це»: Ovo je moj stan.", "fix": {}, "add": [{"hr": "Ovaj autobus ide u centar.", "ua": "Цей автобус їде в центр."}]}, {"topic": "Pokazne zamjenice: ovaj, taj, onaj", "title": "Taj / ta / to — біля співрозмовника", "e": "Taj (ч. р.), ta (ж. р.), to (с. р.) — «цей, той» про те, що поруч зі співрозмовником, або про те, про що щойно говорили. To без іменника — «це, то»: To je točno. Tko je to? — так питаємо і про людей.", "fix": {}, "add": [{"hr": "Tko je to?", "ua": "Хто це?"}]}, {"topic": "Pokazne zamjenice: ovaj, taj, onaj", "title": "Onaj / ona / ono — далеко", "e": "Onaj (ч. р.), ona (ж. р.), ono (с. р.) — «он той, он та, он те» про те, що далеко і від мене, і від співрозмовника. Часто разом із tamo (там): onaj čovjek tamo. Ona «та» і ona «вона» пишуться однаково — різницю видно з речення.", "fix": {}, "add": [{"hr": "Vidiš li onu crkvu tamo?", "ua": "Бачиш он ту церкву?"}]}, {"topic": "Pridjevi: slaganje s imenicom", "title": "Перед іменником: -i / -a / -o", "e": "Прикметник узгоджується з іменником за родом. Перед іменником чоловічий рід зазвичай має -i (novi stan), жіночий -a (nova kuća), середній -o або -e (novo kino, svježe mlijeko). У множині: novi stanovi, nove kuće, nova sela.", "fix": {}, "add": [{"hr": "Ovo je svježe mlijeko.", "ua": "Це свіже молоко."}]}, {"topic": "Pridjevi: slaganje s imenicom", "title": "Після «je»: коротка форма", "e": "Коли прикметник стоїть після je і просто описує предмет, у чоловічому роді вживаємо коротку форму без -i: Stan je nov. Grad je velik. Жіночий і середній рід не змінюються: Kuća je nova. Kino je novo. Перед іменником — довга форма: novi stan.", "fix": {}, "add": [{"hr": "Hotel je skup, ali dobar.", "ua": "Готель дорогий, але хороший."}]}, {"topic": "Upitne riječi", "title": "Основні питання", "e": "Питальне слово ставимо на початок: tko (хто), što (що), gdje (де), kada або kad (коли), kako (як), koliko (скільки), zašto (чому). Після нього — дієслово: Gdje je hotel? Kako se zoveš? Koliko košta?", "fix": {}, "add": [{"hr": "Kako se zoveš?", "ua": "Як тебе звати?"}]}, {"topic": "Upitne riječi", "title": "Де? Куди? Звідки?", "e": "Gdje — де (місце): Gdje si? Kamo (або kuda) — куди (напрямок): Kamo ideš? Odakle — звідки: Odakle ste? Як і в українській, «де» і «куди» — різні слова. Розмовно часто чути «Gdje ideš?», але правильно — Kamo ideš?", "fix": {}, "add": [{"hr": "Kamo idemo večeras?", "ua": "Куди ми підемо сьогодні ввечері?"}]}, {"topic": "Upitne riječi", "title": "Коли ви не зрозуміли", "e": "Коли щось не зрозуміли, не мовчіть: Molim? (Перепрошую?), Možete li ponoviti? (Можете повторити?), Polako, molim vas (Повільніше, будь ласка), Što znači…? (Що означає…?). Хорвати охоче повторять і пояснять, якщо попросити ввічливо.", "fix": {}, "add": [{"hr": "Oprostite, ne razumijem.", "ua": "Вибачте, я не розумію."}]}, {"topic": "Gdje? Prijedlozi mjesta", "title": "U і na + місцевий відмінок", "e": "U — всередині чогось: u sobi, u torbi, u gradu. Na — на поверхні або на відкритому місці: na stolu, na zidu, na plaži. Після обох на питання «де?» іменник у місцевому відмінку: ч. і с. рід мають -u (na stolu, u selu), ж. рід -i (u sobi). Детальніше — в A1.", "fix": {}, "add": [{"hr": "Slika je na zidu.", "ua": "Картина на стіні."}]}, {"topic": "Gdje? Prijedlozi mjesta", "title": "Ispod, iznad, pored + родовий відмінок", "e": "Після ispod (під), iznad (над), pored і pokraj (біля), ispred (перед) та iza (за) іменник стоїть у родовому відмінку: ч. і с. рід мають -a (ispod stola, iza kina), ж. рід -e (pored kuće). В українському «біля столу» — теж родовий, тож логіка знайома.", "fix": {}, "add": [{"hr": "Auto je ispred zgrade.", "ua": "Машина перед будинком."}]}, {"topic": "Gdje? Prijedlozi mjesta", "title": "Ліворуч, праворуч, прямо", "e": "Lijevo (ліворуч), desno (праворуч), ravno (прямо), gore (нагорі, вгору), dolje (внизу, вниз) — прислівники, вони не змінюються. Часто зі skrenite (поверніть): Skrenite lijevo. «З лівого боку» — na lijevoj strani.", "fix": {}, "add": [{"hr": "Skrenite desno kod pošte.", "ua": "Поверніть праворуч біля пошти."}]}, {"topic": "Persiranje: ti i Vi", "title": "Ti — своїм, Vi — незнайомим", "e": "До друзів, родини, дітей і ровесників у неформальній обстановці звертаємося на ti. До незнайомих, старших, у магазині, банку, у лікаря чи в установі — на Vi, і дієслово тоді в множині: Kako ste? Možete li…? На письмі ввічливе Vi пишуть з великої літери.", "fix": {}, "add": [{"hr": "Možete li mi pomoći?", "ua": "Ви можете мені допомогти?"}]}, {"topic": "Persiranje: ti i Vi", "title": "Molim — на всі випадки", "e": "Molim — одне з найпотрібніших слів. Це «будь ласка» в проханні (Molim vas, jednu kavu), «прошу» у відповідь на «дякую» (Hvala! — Molim.) і «перепрошую?», коли не почули (Molim?). Коли щось подаєте, кажуть Izvolite.", "fix": {}, "add": [{"hr": "Račun, molim.", "ua": "Рахунок, будь ласка."}]}, {"topic": "Izgovor: hrvatska slova", "title": "Одна літера — один звук", "e": "Хорватські слова читаємо так, як написано: кожна літера — один звук, нічого не «ковтаємо». Літери h, c, j читаємо як «х», «ц», «й»: hvala, cijena, jaje. Наголос на письмі не позначають — його запам’ятовуємо, коли слухаємо.", "fix": {}, "add": [{"hr": "Hvala, cijena je dobra.", "ua": "Дякую, ціна хороша."}]}, {"topic": "Izgovor: hrvatska slova", "title": "Č і Ć", "e": "Č — тверде «ч», як в українському «час»: čaj, čovjek. Ć — м’якше, щось середнє між «ч» і «ть»: kuća, noć. Багато хорватів у розмові їх майже не розрізняють, але на письмі різниця важлива: kuća, а не «kuča».", "fix": {}, "add": [{"hr": "Laku noć, idem kući.", "ua": "На добраніч, я йду додому."}]}, {"topic": "Izgovor: hrvatska slova", "title": "Š, Ž, Đ, Dž, Lj, Nj", "e": "Š = «ш», ž = «ж», đ — м’який звук, близький до «дь» (đak), dž = «дж», lj = «ль», nj = «нь». Lj, nj і dž — це одна літера, хоч і з двох знаків: ljubav, konj, džep. Без діакритик значення змінюється, тому завжди пишемо š, ž, č, ć, đ.", "fix": {}, "add": [{"hr": "Moja žena voli šetati.", "ua": "Моя дружина любить гуляти."}]}, {"topic": "Niječni i upitni oblici glagola biti", "title": "Заперечення: nisam, nisi, nije…", "e": "Заперечну форму biti пишемо одним словом: ne + sam = nisam, ne + si = nisi, ne + je = nije, далі nismo, niste, nisu. На відміну від sam, ці форми можуть стояти першими: Nisam umorna. «Nije» також означає «його / її немає»: Ana nije ovdje.", "fix": {}, "add": [{"hr": "Nisu kod kuće.", "ua": "Їх немає вдома."}]}, {"topic": "Niječni i upitni oblici glagola biti", "title": "Питання з «li»", "e": "Питання «так / ні» з biti будуємо з повною формою: jesam, jesi, jesmo, jeste, jesu + li: Jesi li dobro? Jeste li iz Ukrajine? Для третьої особи однини кажемо просто Je li…? Порядок: спершу дієслово, потім li, потім решта.", "fix": {}, "add": [{"hr": "Je li restoran otvoren?", "ua": "Ресторан відкритий?"}]}, {"topic": "Niječni i upitni oblici glagola biti", "title": "Коротка відповідь", "e": "На питання з li хорвати часто відповідають не «da / ne», а повною формою дієслова: Jesi li umoran? — Jesam (так) або Nisam (ні). Так само з іншими дієсловами: Imaš li vremena? — Imam. / Nemam.", "fix": {}, "add": [{"hr": "Imate li sobu? — Imamo.", "ua": "У вас є кімната? — Є."}, {"hr": "Je li Daša kod kuće? — Nije.", "ua": "Даша вдома? — Ні."}]}, {"topic": "Brojevi od 0 do 100", "title": "0–10", "e": "Nula, jedan, dva, tri, četiri, pet, šest, sedam, osam, devet, deset — основа всіх чисел. Jedan змінюється за родом: jedan brat, jedna sestra, jedno dijete; dva теж: dva brata, але dvije sestre. Номер телефону диктують по одній цифрі.", "fix": {}, "add": [{"hr": "Imam jednu sestru i dva brata.", "ua": "У мене одна сестра і два брати."}, {"hr": "Soba broj pet je slobodna.", "ua": "Кімната номер п’ять вільна."}]}, {"topic": "Brojevi od 0 do 100", "title": "11–19: «-naest»", "e": "Числа від 11 до 19 мають «-naest»: jedanaest, dvanaest, trinaest, četrnaest, petnaest, šesnaest, sedamnaest, osamnaest, devetnaest. Зверніть увагу: četrnaest і šesnaest (без «t»). Після них іменник у родовому множини: petnaest eura.", "fix": {}, "add": [{"hr": "Autobus dolazi za petnaest minuta.", "ua": "Автобус приїде за п’ятнадцять хвилин."}]}, {"topic": "Brojevi od 0 do 100", "title": "Десятки й сто", "e": null, "fix": {}, "add": [{"hr": "To košta sto eura.", "ua": "Це коштує сто євро."}]}, {"topic": "Brojevi od 0 do 100", "title": "Число + іменник", "e": "Після 1 іменник у називному відмінку: jedan euro, jedna kava. Після 2, 3, 4 — у формі родового однини: dva eura, tri kave. Після 5 і більше — родовий множини: pet eura, deset godina. Так само після 21, 22…: dvadeset jedan euro, dvadeset dva eura.", "fix": {}, "add": [{"hr": "Dvije kave, molim.", "ua": "Дві кави, будь ласка."}]}, {"topic": "Vrijeme: dani, sati, mjeseci", "title": "У який день? — u + день", "e": "На питання «коли? у який день?» кажемо u + день у знахідному відмінку: ponedjeljak → u ponedjeljak, srijeda → u srijedu, subota → u subotu, nedjelja → u nedjelju. Якщо щось буває щотижня, кажемо subotom, nedjeljom — «по суботах, по неділях».", "fix": {}, "add": [{"hr": "Subotom idemo na tržnicu.", "ua": "По суботах ми ходимо на ринок."}]}, {"topic": "Vrijeme: dani, sati, mjeseci", "title": "Учора, сьогодні, завтра", "e": "Prekjučer (позавчора), jučer (учора), danas (сьогодні), sutra (завтра), prekosutra (післязавтра) — прислівники, без прийменника. Частини дня: ujutro (зранку), popodne (по обіді), navečer (увечері), noću (вночі): sutra ujutro — завтра зранку.", "fix": {}, "add": [{"hr": "Vidimo se sutra navečer.", "ua": "Побачимося завтра ввечері."}]}, {"topic": "Vrijeme: dani, sati, mjeseci", "title": "Котра година? О котрій?", "e": "Котра година? — Koliko je sati? Відповідь: jedan sat, dva / tri / četiri sata, від п’яти — sati: Sada je pet sati. О котрій? — U koliko sati? → u osam (sati). Пів години: pola devet = 8:30 (пів на дев’яту).", "fix": {}, "add": [{"hr": "U koliko sati počinje film?", "ua": "О котрій починається фільм?"}, {"hr": "Trgovina radi do osam sati.", "ua": "Магазин працює до восьмої."}]}, {"topic": "Vrijeme: dani, sati, mjeseci", "title": "У якому місяці? — u + місцевий відмінок", "e": "Місяці мають власні хорватські назви: siječanj, veljača, ožujak, travanj, svibanj, lipanj, srpanj, kolovoz, rujan, listopad, studeni, prosinac. «У якому місяці?» — u + місцевий відмінок: u siječnju, u svibnju, u studenome. Назви місяців пишуть з малої літери.", "fix": {}, "add": [{"hr": "Škola počinje u rujnu.", "ua": "Школа починається у вересні."}]}, {"topic": "Rod, množina i posvojne zamjenice", "title": "Три роди", "e": "Рід іменника зазвичай видно із закінчення: чоловічий — на приголосний (brat, grad, stol), жіночий — на -a (sestra, kuća), середній — на -o або -e (selo, more). Винятки: tata і kolega — чоловічого роду, хоч на -a. Від роду залежать прикметник і займенник: moj brat, moja sestra.", "fix": {"0": {"hr": "Moj brat živi u Splitu.", "ua": "Мій брат живе в Спліті."}, "1": {"hr": "Sestra je u školi.", "ua": "Сестра в школі."}, "2": {"hr": "More je toplo.", "ua": "Море тепле."}}, "add": [{"hr": "Ovo je moj tata.", "ua": "Це мій тато."}]}, {"topic": "Rod, množina i posvojne zamjenice", "title": "Мій / моя / моє", "e": "Присвійний займенник має той самий рід, що й іменник: moj brat, moja sestra, moje dijete. Так само tvoj / tvoja / tvoje. Рід визначає річ, а не власник: і Daša, і Marko кажуть «moj brat» і «moja sestra».", "fix": {}, "add": [{"hr": "Gdje je moj mobitel?", "ua": "Де мій мобільний?"}]}, {"topic": "Rod, množina i posvojne zamjenice", "title": "Множина", "e": "Множина: чоловічий рід отримує -i (prijatelj → prijatelji), жіночий -a → -e (kuća → kuće), середній -o / -e → -a (selo → sela, more → mora). Більшість коротких (односкладових) слів чоловічого роду мають -ovi / -evi: grad → gradovi (див. наступне правило). Особливі: brat → braća, dijete → djeca, čovjek → ljudi.", "fix": {}, "add": [{"hr": "Ljudi su ovdje ljubazni.", "ua": "Люди тут привітні."}]}, {"topic": "Red riječi", "title": "Звичайний порядок", "e": "Як і в українській, звичайний порядок — хто, що робить, що / де: Ja pijem kavu. Ana radi u banci. Порядок досить вільний, і найважливіше часто ставлять у кінець: Kavu pijem ujutro (наголос на «коли»). Головне правило — короткі слова на другому місці (див. далі).", "fix": {}, "add": [{"hr": "U subotu idemo u kino.", "ua": "У суботу ми йдемо в кіно."}]}, {"topic": "Red riječi", "title": "Короткі слова — на другому місці", "e": "Короткі (ненаголошені) слова — sam, si, je, smo, ste, su, se, me, te, li — стоять на другому місці в реченні: після першого слова або першої групи слів. Тому Zovem se Ana, а не «Se zovem Ana»; Umoran sam, а не «Sam umoran».", "fix": {}, "add": [{"hr": "Danas sam kod kuće.", "ua": "Сьогодні я вдома."}]}, {"topic": "Red riječi", "title": "Питання", "e": "Питання «так / ні» починаємо з дієслова + li: Imate li…? Govorite li…? З biti — Je li…? Jesi li…? Розмовно чути й «Da li…?», але в хорватській нормі краще дієслово + li. Якщо є питальне слово, воно стоїть першим: Gdje…? Kada…?", "fix": {}, "add": [{"hr": "Zašto si tužan?", "ua": "Чому ти сумний?"}]}, {"topic": "Redni brojevi", "title": "Перший … десятий", "e": null, "fix": {"0": {"hr": "Ovo mi je prvi dan na poslu.", "ua": "Це мій перший день на роботі."}}, "add": [{"hr": "Živim u drugoj ulici lijevo.", "ua": "Я живу на другій вулиці ліворуч."}]}, {"topic": "Redni brojevi", "title": "Як прикметник", "e": "Порядкове число узгоджується з іменником і відмінюється, як прикметник: prvi kat, prva ulica, prvo mjesto. «На якому поверсі?» — na prvom, drugom, trećem katu; «у першому класі» — u prvom razredu.", "fix": {}, "add": [{"hr": "Moj ured je na petom katu.", "ua": "Мій офіс на п’ятому поверсі."}]}, {"topic": "Redni brojevi", "title": "Цифра з крапкою", "e": "Порядкове число цифрою пишемо з крапкою після цифри: 3. kat = treći kat, 5. razred = peti razred. Так само в датах: 1. svibnja = prvi svibnja (місяць у родовому відмінку). Крапка тут обов’язкова, без неї це звичайне число.", "fix": {}, "add": [{"hr": "Ured je na 4. katu.", "ua": "Офіс на 4-му поверсі."}]}, {"topic": "Veliki brojevi: stotine, tisuće, milijuni", "title": "Сотні", "e": null, "fix": {}, "add": [{"hr": "Stan košta petsto eura mjesečno.", "ua": "Квартира коштує п’ятсот євро на місяць."}]}, {"topic": "Veliki brojevi: stotine, tisuće, milijuni", "title": "Тисячі, мільйони, мільярди", "e": null, "fix": {}, "add": [{"hr": "Zagreb ima oko osamsto tisuća stanovnika.", "ua": "У Загребі близько вісімсот тисяч жителів."}]}, {"topic": "Veliki brojevi: stotine, tisuće, milijuni", "title": "Як читати довге число", "e": "Довге число читаємо зліва направо: тисячі, сотні, десятки, одиниці — без «і» між ними: 2026 — dvije tisuće dvadeset šest. Рік народження часто кажуть коротко порядковим числом: devedeset druge — 1992-го (godište).", "fix": {}, "add": [{"hr": "Telefon košta tisuću dvjesto eura.", "ua": "Телефон коштує тисячу двісті євро."}]}, {"topic": "Veliki brojevi: stotine, tisuće, milijuni", "title": "Рахуємо вголос", "e": "Арифметика вголос: plus (плюс), minus (мінус), puta (помножити на), podijeljeno s (поділити на). «Дорівнює» — je або jednako je: Dva plus dva je četiri. Puta означає також «разів»: tri puta tjedno — тричі на тиждень.", "fix": {}, "add": [{"hr": "Treniram tri puta tjedno.", "ua": "Я тренуюся тричі на тиждень."}]}, {"topic": "Veliki brojevi: stotine, tisuće, milijuni", "title": "Приблизно, частини, відсотки", "e": null, "fix": {}, "add": [{"hr": "Popust je dvadeset posto.", "ua": "Знижка двадцять відсотків."}]}, {"topic": "Vrijeme: bezlične rečenice", "title": "Холодно, тепло: прислівник + je", "e": null, "fix": {}, "add": [{"hr": "Ljeti je u Splitu vruće.", "ua": "Влітку в Спліті спекотно."}]}, {"topic": "Vrijeme: bezlične rečenice", "title": "Дощ «падає», вітер «дме»", "e": "Про опади хорвати кажуть «падає»: pada kiša (іде дощ), pada snijeg (іде сніг). Про вітер — «дме»: puše vjetar, puše bura (холодний північний вітер), puše jugo (теплий південний). Українське «іде дощ» дослівно перекладати не можна.", "fix": {}, "add": [{"hr": "Puše jugo, more je nemirno.", "ua": "Дме юго, море неспокійне."}]}, {"topic": "Vrijeme: bezlične rečenice", "title": "Було й буде: bilo je, bit će", "e": "Минуле про погоду: bilo je + прислівник: Jučer je bilo hladno (учора було холодно). Майбутнє: bit će: Sutra će biti toplo. Bit će kiše — «буде дощ» (kiša в родовому). Минулий і майбутній час докладно — в A1, тут це готові вирази.", "fix": {}, "add": [{"hr": "Prošli tjedan bilo je jako vruće.", "ua": "Минулого тижня було дуже спекотно."}]}, {"topic": "Posvojne zamjenice", "title": "Мій, твій, наш, ваш", "e": null, "fix": {}, "add": [{"hr": "Vaša putovnica, molim.", "ua": "Ваш паспорт, будь ласка."}]}, {"topic": "Posvojne zamjenice", "title": "Його, її, їхній", "e": null, "fix": {}, "add": [{"hr": "Njegov sin živi u Rijeci.", "ua": "Його син живе в Рієці."}]}, {"topic": "Posvojne zamjenice", "title": "Svoj — «свій»", "e": null, "fix": {}, "add": [{"hr": "Marko voli svoju ženu.", "ua": "Марко любить свою дружину."}]}, {"topic": "Posvojne zamjenice", "title": "Чий? Чия? Чиє?", "e": "Питання про власника теж узгоджується з річчю: čiji (ч. р.), čija (ж. р.), čije (с. р.), у множині — čiji, čije, čija. Відповідаємо присвійним займенником: Čija je ovo torba? — Moja. Čiji je ovo mobitel? — Njegov.", "fix": {}, "add": [{"hr": "Čije su ovo cipele?", "ua": "Чиї це черевики?"}]}, {"topic": "Komparativ: jeftiniji, skuplji", "title": "Дешевший, дорожчий: -iji і -ji", "e": null, "fix": {}, "add": [{"hr": "Ovaj stan je jeftiniji.", "ua": "Ця квартира дешевша."}]}, {"topic": "Komparativ: jeftiniji, skuplji", "title": "Дешевше, дорожче, більше", "e": null, "fix": {}, "add": [{"hr": "Danas je sve skuplje.", "ua": "Сьогодні все дорожче."}]}, {"topic": "Komparativ: jeftiniji, skuplji", "title": "Ніж: nego або od", "e": null, "fix": {}, "add": [{"hr": "Vlak je brži od autobusa.", "ua": "Поїзд швидший за автобус."}]}, {"topic": "Komparativ: jeftiniji, skuplji", "title": "Найдешевший: naj-", "e": "Найвищий ступінь: naj- + вищий ступінь: jeftiniji → najjeftiniji, skuplji → najskuplji, bolji → najbolji, veći → najveći. Він узгоджується з іменником, як прикметник: najbolja cijena, najveći grad. «З усіх» — od svih: najjeftiniji od svih.", "fix": {}, "add": [{"hr": "Zagreb je najveći grad u Hrvatskoj.", "ua": "Загреб — найбільше місто Хорватії."}]}, {"topic": "Što te boli? Boli me…, bole me…", "title": "Мене болить: boli me", "e": null, "fix": {}, "add": [{"hr": "Boli ga glava.", "ua": "У нього болить голова."}]}, {"topic": "Što te boli? Boli me…, bole me…", "title": "Болить чи болять: boli / bole", "e": "Дієслово узгоджується з тим, що болить: одна річ — boli (boli me noga), кілька — bole (bole me noge). Leđa (спина) і prsa (груди) мають лише множину, тому кажуть bole me leđa, bole me prsa, хоча українською «болить спина».", "fix": {}, "add": [{"hr": "Boli me noga.", "ua": "У мене болить нога."}]}, {"topic": "Što te boli? Boli me…, bole me…", "title": "Що болить? Питання й заперечення", "e": "Лікар запитає: Što vas boli? або Gdje vas boli? (до знайомих — te). Відповідаємо: Boli me ovdje. Заперечення — ne перед дієсловом: Ne boli me. Više me ne boli — «уже не болить». Питання з li: Boli li vas glava?", "fix": {}, "add": [{"hr": "Boli li vas ovdje?", "ua": "Вам тут болить?"}]}, {"topic": "Veznici", "title": "I, a, ali", "e": "I — «і» (з’єднує): brat i sestra. A — «а» (протиставляє двох людей чи дві речі): Ja radim, a on spava. Ali — «але» (обмеження, несподіванка): Mali je, ali lijep. Перед a і ali ставимо кому, перед i — ні.", "fix": {}, "add": [{"hr": "Volim more, ali ne volim vrućinu.", "ua": "Я люблю море, але не люблю спеку."}]}, {"topic": "Veznici", "title": "Ili — або, чи", "e": "Ili — «або, чи»: вибір між варіантами. У питанні: Kava ili čaj? У проханні: Platite karticom ili gotovinom. «Або… або…» — ili… ili…: Doći ću ili danas ili sutra. Перед ili кома зазвичай не потрібна.", "fix": {}, "add": [{"hr": "Idemo autom ili vlakom?", "ua": "Їдемо машиною чи поїздом?"}]}, {"topic": "Veznici", "title": "Jer, zato što — бо, тому що", "e": "Причину пояснюємо словами jer або zato što — «бо, тому що»: Ne dolazim jer sam bolestan. На питання Zašto? (чому?) зазвичай відповідають Zato što…: Zašto učiš hrvatski? — Zato što živim ovdje. Обидва слова означають те саме.", "fix": {"1": {"hr": "Ne idem zato što sam umorna.", "ua": "Я не йду, бо втомилася."}}, "add": [{"hr": "Zašto kasniš? — Zato što nema autobusa.", "ua": "Чому ти запізнюєшся? — Бо немає автобуса."}]}, {"topic": "Pravilni glagoli", "title": "Інфінітив: -ti або -ći", "e": "У словнику дієслово стоїть в інфінітиві. Більшість мають -ti (raditi, gledati, piti), частина — -ći (ići, moći, doći, peći). Від інфінітива утворюємо теперішній час: gledati → gledam, raditi → radim. У майбутньому часі -i відпадає: radit ću (див. Futur I).", "fix": {}, "add": [{"hr": "Moram kupiti kruh.", "ua": "Мені треба купити хліб."}]}, {"topic": "Pravilni glagoli", "title": "Дієслово + інфінітив", "e": "Після voljeti (любити), željeti (бажати), htjeti (хотіти), moći (могти), morati (мусити), znati (уміти) і učiti (вчитися) друге дієслово стоїть в інфінітиві — як в українському «люблю плавати». Конструкцію «želim da idem» хорватська норма не радить — кажіть Želim ići.", "fix": {}, "add": [{"hr": "Znaš li plivati?", "ua": "Ти вмієш плавати?"}]}, {"topic": "Pravilni glagoli", "title": "Питання і заперечення", "e": "Питання «так / ні»: дієслово + li на початку: Čitaš li? Radite li danas? Заперечення: ne окремо перед дієсловом: Ne čitam. Ne radimo. Коротка відповідь — тим самим дієсловом: Radiš li sutra? — Radim. / Ne radim.", "fix": {}, "add": [{"hr": "Radite li u subotu? — Ne radimo.", "ua": "Ви працюєте в суботу? — Ні."}]}, {"topic": "Česti nepravilni glagoli", "title": "Ići — іти, їхати", "e": "Ići означає і «йти пішки», і «їхати»: Idem na posao (пішки чи автобусом — не важливо). Як саме — додаємо: idem pješice, idem autobusom. Теперішній час: idem, ideš, ide, idemo, idete, idu. «Ходімо!» — Idemo!", "fix": {}, "add": [{"hr": "Idemo na kavu!", "ua": "Ходімо на каву!"}]}, {"topic": "Česti nepravilni glagoli", "title": "Htjeti і moći", "e": null, "fix": {}, "add": [{"hr": "Hoćete li još nešto?", "ua": "Бажаєте ще щось?"}]}, {"topic": "Česti nepravilni glagoli", "title": "Jesti і piti", "e": null, "fix": {}, "add": [{"hr": "Pijete li kavu sa šećerom?", "ua": "Ви п’єте каву з цукром?"}]}, {"topic": "Akuzativ", "title": "Жіночий рід: -a → -u", "e": "Знахідний відмінок відповідає на питання «кого? що?» після дієслів imati, trebati, vidjeti, kupovati, voljeti. Іменники жіночого роду на -a мають -u — як в українському «кава — каву»: Pijem kavu. Trebam kartu. Прикметник теж: novu kartu.", "fix": {}, "add": [{"hr": "Trebam kartu za Split.", "ua": "Мені потрібен квиток до Спліта."}]}, {"topic": "Akuzativ", "title": "Чоловічий рід: неживе не змінюється, живе → -a", "e": "Неживі іменники чоловічого роду в знахідному не змінюються: Trebam ključ. Kupujem kruh. Живі (люди й тварини) отримують -a: Čekam prijatelja. Imam psa. Середній рід теж не змінюється: Pijem vino. Як в українському «бачу стіл — бачу брата».", "fix": {}, "add": [{"hr": "Tražim liječnika.", "ua": "Я шукаю лікаря."}]}, {"topic": "Akuzativ", "title": "Займенники: me, te, ga, je", "e": "Короткі форми займенників у знахідному: me (мене), te (тебе), ga (його), je (її), nas, vas, ih (їх). Вони стоять на другому місці: Vidim te. Zovem ga sutra. Повні форми (mene, tebe, njega, nju) — для наголосу або після прийменника: Čekam tebe, ne njega.", "fix": {}, "add": [{"hr": "Čekam tebe, a ne njega.", "ua": "Я чекаю тебе, а не його."}]}, {"topic": "Prezent", "title": "Дієслова на -am: čitati", "e": "Дієслова на -ati здебільшого відмінюються як čitati: -am, -aš, -a, -amo, -ate, -aju. Так само gledati, slušati, čekati, ručati. Основа не змінюється — це найлегша група. Але частина дієслів на -ati має -em: pisati → pišem (див. далі).", "fix": {"1": {"hr": "Kada ručaš?", "ua": "Коли ти обідаєш?"}}, "add": [{"hr": "Čekamo autobus.", "ua": "Ми чекаємо автобус."}]}, {"topic": "Prezent", "title": "Дієслова на -im: govoriti", "e": "Дієслова на -iti і більшість на -jeti мають -im, -iš, -i, -imo, -ite, -e: govoriti → govorim, raditi → radim, živjeti → živim, vidjeti → vidim. У третій особі множини — -e: oni govore, oni rade, oni žive.", "fix": {"1": {"hr": "Gdje radiš?", "ua": "Де ти працюєш?"}}, "add": [{"hr": "Vidim more s balkona.", "ua": "Я бачу море з балкона."}]}, {"topic": "Prezent", "title": "Дієслова на -em: pisati, piti, doručkovati", "e": "Решта дієслів мають -em, -eš, -e, -emo, -ete, -u. Основа часто змінюється, тому форму «я …» варто вчити разом з інфінітивом: pisati → pišem, piti → pijem, doručkovati → doručkujem, jesti → jedem. У третій особі множини — -u: oni pišu.", "fix": {}, "add": [{"hr": "Djeca piju sok.", "ua": "Діти п’ють сік."}]}, {"topic": "Genitiv: osnove", "title": "Кількість + родовий", "e": "Після слів кількості — kilogram, litra, boca, šalica, komad, malo, puno — іменник стоїть у родовому відмінку: жіночий рід -a → -e (boca vode), чоловічий і середній отримують -a (kilogram sira, malo mlijeka). Українською так само: пляшка води, трохи сиру.", "fix": {}, "add": [{"hr": "Šalicu čaja, molim.", "ua": "Чашку чаю, будь ласка."}]}, {"topic": "Genitiv: osnove", "title": "Nema + родовий", "e": "Nema — «немає»: те, чого немає, стоїть у родовому відмінку: nema mlijeka, nema autobusa. Nemam — «у мене немає»: nemam vremena, nemam novca. Так само в минулому: nije bilo vode — не було води.", "fix": {}, "add": [{"hr": "Nemam novca kod sebe.", "ua": "У мене немає з собою грошей."}]}, {"topic": "Genitiv: osnove", "title": "Iz, od, do, kod, preko puta + родовий", "e": "Після iz (з, зсередини), od (від), do (до), kod (біля; у когось) і preko puta (навпроти) іменник стоїть у родовому відмінку: iz Ukrajine, od kuće, do centra, kod liječnika, preko puta pošte. Kod часто означає «у когось удома чи в кабінеті»: kod mame, kod zubara.", "fix": {}, "add": [{"hr": "Večeras smo kod prijatelja.", "ua": "Сьогодні ввечері ми в друзів."}]}, {"topic": "Lokativ", "title": "Де? — u / na + місцевий", "e": "На питання «де?» після u і na — місцевий відмінок. Чоловічий і середній рід отримують -u: grad → u gradu, more → na moru. Жіночий рід на -a має -i: kuća → u kući, plaža → na plaži. Прикметник: u novom stanu, na velikoj plaži.", "fix": {}, "add": [{"hr": "Djeca su u vrtiću.", "ua": "Діти в садочку."}]}, {"topic": "Lokativ", "title": "U чи na?", "e": "U — всередині закритого простору: u stanu, u trgovini, u gradu. Na — на поверхні, на відкритому місці і в сталих виразах, які треба запам’ятати: na moru, na poslu, na tržnici, na otoku, na pošti, na fakultetu, na koncertu. Українське «на роботі» — теж na poslu.", "fix": {}, "add": [{"hr": "Kupujem marke na pošti.", "ua": "Я купую марки на пошті."}]}, {"topic": "Lokativ", "title": "O + місцевий: про кого, про що", "e": "Після o («про») — теж місцевий відмінок: pričamo o poslu, čitam o Hrvatskoj. Так само після po (по): šetamo po gradu. Питання — O čemu? (про що?) O kome? (про кого?). Займенники після o — повні: o meni, o tebi, o njoj.", "fix": {}, "add": [{"hr": "O čemu razgovarate?", "ua": "Про що ви розмовляєте?"}]}, {"topic": "Posvojne zamjenice", "title": "Naš, vaš", "e": "Naš — «наш», vaš — «ваш». Закінчення — як у прикметника і залежать від речі: naš stan, naša kuća, naše dijete; множина: naši prijatelji, naše kuće. Ввічливе Vaš (до однієї людини на «Ви») пишуть з великої літери: Je li ovo Vaša torba?", "fix": {}, "add": [{"hr": "Naši susjedi su iz Osijeka.", "ua": "Наші сусіди з Осієка."}]}, {"topic": "Posvojne zamjenice", "title": "Njegov, njezin, njihov", "e": "Njegov — «його», njezin — «її», njihov — «їхній». На відміну від української, вони змінюються за родом і числом речі: njegov auto, njegova kuća; njezin brat, njezina sestra; njihovo dijete. Розмовно чути njen, але в хорватській нормі — njezin.", "fix": {}, "add": [{"hr": "Njihov sin studira u Zagrebu.", "ua": "Їхній син навчається в Загребі."}]}, {"topic": "Posvojne zamjenice", "title": "Čiji? — чий?", "e": "Питання про власника: čiji (ч. р.), čija (ж. р.), čije (с. р.) — узгоджується з річчю, а не з власником: Čiji je ovo ključ? Čija je ovo torba? У множині: Čiji su ovo ključevi? Відповідаємо присвійним займенником: Moj. Njezina.", "fix": {"2": {"hr": "Čiji su ovo ključevi?", "ua": "Чиї це ключі?"}}, "add": [{"hr": "Čije je ovo dijete?", "ua": "Чия це дитина?"}]}, {"topic": "Modalni glagoli", "title": "Moći — могти", "e": "Moći — «могти»: mogu, možeš, može, možemo, možete, mogu. Mogu li…? — найпростіше ввічливе прохання: Mogu li platiti karticom? (Можна карткою?) Možete li…? — прохання до когось: Možete li mi pomoći? Після moći — інфінітив.", "fix": {}, "add": [{"hr": "Možemo li sjesti ovdje?", "ua": "Можна нам сісти тут?"}]}, {"topic": "Modalni glagoli", "title": "Morati і trebati", "e": "Morati — «мусити»: Moram ići (мені треба йти). Trebati + іменник — «мені потрібне щось»: Trebam liječnika, Trebam vrećicu. Також кажуть безособово: Treba mi pomoć — «мені потрібна допомога». Ne moraš означає «не обов’язково», а не «не можна» (див. далі).", "fix": {}, "add": [{"hr": "Treba mi tvoj broj.", "ua": "Мені потрібен твій номер."}]}, {"topic": "Modalni glagoli", "title": "Smjeti — можна (дозвіл)", "e": "Smjeti — «мати дозвіл»: smijem, smiješ, smije, smijemo, smijete, smiju. Smijem li…? — «Чи можна мені…?»: Smijem li ući? Ne smijete — «вам не можна» (заборона): Ovdje ne smijete pušiti. На табличках пишуть Zabranjeno pušenje.", "fix": {}, "add": [{"hr": "Smijem li otvoriti prozor?", "ua": "Можна відчинити вікно?"}]}, {"topic": "Imperativ", "title": "Ти: -i / -j", "e": "Наказ або прохання до однієї людини на «ти». Дієслова на -ati: основа + -j: čekati → čekaj, dodati → dodaj. Більшість інших: основа теперішнього часу + -i: uzeti (uzmem) → uzmi, pisati (pišem) → piši, doći (dođem) → dođi. З molim te звучить м’якше: Dodaj mi sol, molim te.", "fix": {}, "add": [{"hr": "Uzmi kišobran, pada kiša.", "ua": "Візьми парасольку, іде дощ."}]}, {"topic": "Imperativ", "title": "Ви: -ite / -jte", "e": "До кількох людей або ввічливо до однієї на «Vi» додаємо -te: čekaj → čekajte, uzmi → uzmite, dođi → dođite. Так звучать інструкції: Ispunite obrazac. Uzmite broj. Pričekajte. Izvolite — «прошу» (коли щось пропонують).", "fix": {}, "add": [{"hr": "Ispunite ovaj obrazac, molim.", "ua": "Заповніть цю форму, будь ласка."}]}, {"topic": "Imperativ", "title": "Не роби: nemoj / nemojte + інфінітив", "e": "Щоб сказати «не роби», хорвати зазвичай вживають nemoj (до «ти») або nemojte (до «Vi») + інфінітив: Nemoj kasniti! Nemojte parkirati ovdje. Це звучить м’якше, ніж «Ne kasni!». На табличках — Zabranjeno… (заборонено).", "fix": {}, "add": [{"hr": "Nemojte se brinuti, sve je u redu.", "ua": "Не хвилюйтеся, усе гаразд."}]}, {"topic": "Komparacija pridjeva", "title": "Вищий ступінь: -iji, -ji", "e": "Вищий ступінь найчастіше має -iji: jeftin → jeftiniji, nov → noviji, topao → topliji. Деякі прикметники мають -ji і змінюють приголосний: skup → skuplji, drag → draži, tih → tiši, brz → brži. Неправильні треба запам’ятати: velik → veći, mali → manji, dobar → bolji, loš → gori.", "fix": {}, "add": [{"hr": "Ova soba je tiša.", "ua": "Ця кімната тихіша."}]}, {"topic": "Komparacija pridjeva", "title": "Ніж: nego", "e": "Порівнюємо дві речі: X je … nego Y — «X …-іший, ніж Y»: Split je topliji nego Zagreb. Після nego слово не змінюється. Можна сказати й od + родовий: topliji od Zagreba. «Набагато» — puno або mnogo: puno jeftiniji.", "fix": {}, "add": [{"hr": "Ovaj telefon je puno jeftiniji od onog.", "ua": "Цей телефон набагато дешевший за той."}]}, {"topic": "Komparacija pridjeva", "title": "Найвищий ступінь: naj-", "e": "Найвищий ступінь: naj- + вищий ступінь: najbolji, najjeftiniji, najveći, najljepši. Він узгоджується з іменником: najbolja pekara, najveći grad. «Найкращий у…» — u + місцевий: najbolji u gradu; «з усіх» — od svih.", "fix": {"1": {"hr": "Ljeto je najtoplije godišnje doba.", "ua": "Літо — найтепліша пора року."}}, "add": [{"hr": "Ovo je najljepša plaža u Hrvatskoj.", "ua": "Це найкрасивіший пляж у Хорватії."}]}, {"topic": "Upitne rečenice", "title": "Питання з li", "e": "Питання «так / ні»: дієслово + li на початку речення: Imate li…? Možete li…? Govorite li…? З biti: Je li…? Jesi li…? Jeste li…? Розмовно ви почуєте й «Da li…?», але в хорватській нормі краще дієслово + li.", "fix": {}, "add": [{"hr": "Možete li mi pokazati put?", "ua": "Можете показати мені дорогу?"}]}, {"topic": "Upitne rečenice", "title": "Питальні слова", "e": "Основні питальні слова: kada (коли), koliko (скільки), zašto (чому), kako (як), odakle (звідки), kamo (куди), gdje (де), tko (хто), što (що). Вони стоять на початку питання, після них — дієслово: Koliko košta? Zašto kasniš? Kamo ideš?", "fix": {}, "add": [{"hr": "Kako se ovo kaže na hrvatskom?", "ua": "Як це сказати хорватською?"}]}, {"topic": "Upitne rečenice", "title": "Koji і kakav — який?", "e": "Koji — «який саме» (вибір з кількох): Koji autobus ide u centar? Kakav — «який, якої якості, на вигляд»: Kakvo je vrijeme? Kakav je stan? Обидва узгоджуються з іменником: koja ulica, kakva kuća, koje dijete.", "fix": {}, "add": [{"hr": "Koja je tvoja omiljena boja?", "ua": "Який твій улюблений колір?"}]}, {"topic": "Nijekanje", "title": "Ne + дієслово", "e": "Заперечення: ne ставимо окремо перед дієсловом: ne razumijem, ne znam, ne radi. Разом пишемо лише кілька злитих форм (nisam, nemam, neću — далі). Якщо в реченні є короткі слова, ne стоїть перед ними: Ne sviđa mi se.", "fix": {}, "add": [{"hr": "Ne razumijem, možete li ponoviti?", "ua": "Не розумію, можете повторити?"}]}, {"topic": "Nijekanje", "title": "Nisam, nemam, neću, nema", "e": "Три дієслова зливаються з ne в одне слово: biti → nisam, nisi, nije…; imati → nemam, nemaš, nema…; htjeti → neću, nećeš, neće… «Nema» також означає «немає» взагалі: Nema problema. Neću часто означає «не буду» (майбутнє): Neću doći.", "fix": {}, "add": [{"hr": "Danas nije hladno.", "ua": "Сьогодні не холодно."}]}, {"topic": "Nijekanje", "title": "Подвійне заперечення", "e": "Як і в українській, nitko (ніхто), ništa (нічого), nikad (ніколи), nigdje (ніде) вимагають ще й ne перед дієсловом: Nitko ne zna. Ništa ne vidim. Nikad ne kasnim. Сказати «Nitko zna» — помилка.", "fix": {}, "add": [{"hr": "Nigdje ne mogu naći ključeve.", "ua": "Я ніде не можу знайти ключі."}]}, {"topic": "Neodređene zamjenice: netko, nešto, negdje", "title": "Sve-: svatko, sve, svugdje", "e": "Слова на sve- і svi означають «усі, кожен»: svatko — кожен (Svatko može doći), svi — усі (Svi su tu?), sve — усе (Sve je u redu), svugdje — всюди, uvijek — завжди. Svatko — однина: Svatko zna; svi — множина: Svi znaju.", "fix": {"2": {"hr": "Svugdje je gužva.", "ua": "Скрізь людно."}}, "add": []}, {"topic": "Vokativ: Dašo! Ivane! Gospodine!", "title": "Множина: Djeco! Dragi prijatelji!", "e": "У множині кличний здебільшого такий самий, як називний: Prijatelji!, Kolege!, Dragi prijatelji! Але є два часті винятки, які варто запам’ятати: djeca → Djeco! і gospoda → Gospodo! (Dame i gospodo!).", "fix": {}, "add": []}]'::jsonb) as t(topic text, title text, e text, fix jsonb, "add" jsonb)
  loop
    -- тему, якої немає в цій базі (локальна / CI без базових тем), пропускаємо; у робочій базі всі є —
    -- це перевіряє самоперевірка нижче (жодного правила A0 / A1 < 150 знаків чи < 4 прикладів)
    if not exists (select 1 from public.grammar_topics where title_hr = r.topic and cefr in ('A0', 'A1') and status = 'PUBLISHED') then
      raise notice 'Теми «%» немає — пропущено', r.topic;
      continue;
    end if;
    g := null;
    select gr.* into g from public.grammar_rules gr join public.grammar_topics gt on gt.id = gr.topic_id
     where gt.title_hr = r.topic and gt.cefr in ('A0', 'A1') and gt.status = 'PUBLISHED' and gr.title_ua = r.title;
    if g.id is null then raise exception 'Правило «%» / «%» не знайдено', r.topic, r.title; end if;
    v_ex := coalesce(g.examples, '[]'::jsonb);
    for k in select jsonb_object_keys(r.fix) loop
      v_ex := jsonb_set(v_ex, array[k], r.fix -> k);
    end loop;
    for a in select * from jsonb_array_elements(r."add") loop
      if not exists (select 1 from jsonb_array_elements(v_ex) e where e ->> 'hr' = a ->> 'hr') then
        v_ex := v_ex || jsonb_build_array(a);
      end if;
    end loop;
    if v_ex is distinct from g.examples or (r.e is not null and r.e is distinct from g.explanation_ua) then
      insert into public.content_versions (entity_type, entity_id, version, payload, change_reason)
      values ('grammar_rule', g.id,
              coalesce((select max(version) from public.content_versions where entity_type = 'grammar_rule' and entity_id = g.id), 0) + 1,
              to_jsonb(g), 'core_words_20261104: довше пояснення й приклади — стара версія');
      update public.grammar_rules set explanation_ua = coalesce(r.e, explanation_ua), examples = v_ex where id = g.id;
      insert into public.content_reviews (entity_type, entity_id, from_status, to_status, verdict, reviewer_kind, findings, notes)
      values ('grammar_rule', g.id, 'PUBLISHED', 'PUBLISHED', 'auto_passed', 'ai', '[]'::jsonb, 'Аудит A0 + A1 2026-11-04: довше пояснення й приклади / нове правило. Потрібна перевірка носієм.');
      v_changed := v_changed + 1;
    end if;
  end loop;
  raise notice 'Оновлено правил: %', v_changed;
end
$rules$;

-- ---------------------------------------------------------------- 4. cefr = рівень першого уроку
do $cefr$
declare
  x record;
  v_changed int := 0;
begin
  for x in
    select l.*, f.lv from public.lexemes l
    join (select li.item_id, min(le.level_code) lv from public.lesson_items li
            join public.lessons le on le.id = li.lesson_id and le.status = 'PUBLISHED' and le.level_code in ('A0', 'A1')
           where li.item_type = 'lexeme' group by li.item_id) f on f.item_id = l.id
    where l.cefr is distinct from f.lv
  loop
    insert into public.content_versions (entity_type, entity_id, version, payload, change_reason)
    values ('lexeme', x.id,
            coalesce((select max(version) from public.content_versions where entity_type = 'lexeme' and entity_id = x.id), 0) + 1,
            to_jsonb(x) - 'lv', 'core_words_20261104: cefr ' || coalesce(x.cefr, 'null') || ' → ' || x.lv || ' — стара версія');
    update public.lexemes set cefr = x.lv, version = coalesce(version, 1) + 1 where id = x.id;
    v_changed := v_changed + 1;
  end loop;
  if v_changed > 0 then
    insert into public.content_reviews (entity_type, entity_id, from_status, to_status, verdict, reviewer_kind, findings, notes)
    select 'lexeme', id, status, status, 'auto_passed', 'script', '[]'::jsonb, 'Аудит A0 + A1 2026-11-04: cefr = рівень уроку, де слово вперше вчать (рішення власника).'
      from public.lexemes l
     where exists (select 1 from public.content_versions v where v.entity_type = 'lexeme' and v.entity_id = l.id
                     and v.change_reason like 'core_words_20261104: cefr%')
       and not exists (select 1 from public.content_reviews r where r.entity_type = 'lexeme' and r.entity_id = l.id
                         and r.notes = 'Аудит A0 + A1 2026-11-04: cefr = рівень уроку, де слово вперше вчать (рішення власника).');
  end if;
  raise notice 'Мітки cefr: змінено %', v_changed;
end
$cefr$;

-- ---------------------------------------------------------------- Самоперевірка (інакше — усе відкочується)
do $$
declare v_bad int;
begin
  select count(*) into v_bad from jsonb_array_elements_text('["puno", "tako", "vidjeti", "čuti", "reći", "ili", "problem", "dobar", "pisati", "ali", "kada", "kao", "možda", "loš", "trebati", "željeti", "sve", "topao", "važan", "roditelj", "sjediti", "ako", "čitati", "svaki", "trčati", "gledati", "jer", "lak", "vrlo", "dom", "razgovarati", "slušati", "dok", "život"]'::jsonb) w
   where not exists (select 1 from public.lesson_items li join public.lexemes x on x.id = li.item_id
                     join public.lessons le on le.id = li.lesson_id and le.status = 'PUBLISHED'
                      where li.item_type = 'lexeme' and lower(x.lemma) = w);
  if v_bad > 0 then raise exception 'Базових слів не в уроках: %', v_bad; end if;
  select count(*) into v_bad from (select li.lesson_id from public.lesson_items li join public.lessons le on le.id = li.lesson_id
      where li.item_type = 'lexeme' and le.id in ('c0000000-0000-0000-0000-000000000001'::uuid, 'd8cffb46-8a62-538a-b864-e227a6d8b863'::uuid, 'a17f2f16-1be9-50f2-8e16-2bebfcced33b'::uuid, 'e704760a-f743-5762-9c1a-027b10ca030a'::uuid, '2b6ed342-cc80-5bd9-baf0-b66109624d62'::uuid, '04167753-db83-5163-a91c-9f71dac18ab5'::uuid, '8f6439a9-c6ac-5271-99c8-1f0adc5d7599'::uuid, '2fa5fa38-9641-5dc5-9156-6a3f7fe8035b'::uuid, '3b51b1bf-47f4-5709-96d9-c518d36440e6'::uuid, '22dd7878-4fa8-5e1c-909e-71c70ffd9918'::uuid, '036fc4fb-1bf2-5100-9fd0-6f6a612554a1'::uuid, 'd7cf3059-0d92-5215-8ef4-ad699e317b10'::uuid, '4e003796-1ce0-5a02-8a2d-59a0de38f3dd'::uuid, '2b0e9742-99e1-57e1-a574-67ffb78d2607'::uuid, '78f28f85-dd8b-5e81-8a52-1b2dbce4eb34'::uuid, '4bf48151-be83-5108-bc92-645c0603a1a3'::uuid, '959e879f-a28d-5bed-9c09-16cff91ef456'::uuid, 'd43d6c65-1ce3-5c72-9ecd-cce2ed200fc2'::uuid, '63a4a6d8-1cae-5e0e-90ff-98efcfe8b4c7'::uuid, 'ad0bc1f4-2808-5b24-969d-9da64d4a7a4d'::uuid, 'b369f01f-4a84-57b4-98cb-150d236f4d7f'::uuid, 'd813e9c0-2331-59d8-90f1-cea7e9a61c7d'::uuid, '1c16ceee-5f42-536a-98b4-7dcabaa3be6d'::uuid, '3f440ad8-f057-5898-b773-6aa8816fa8a3'::uuid, 'dbb91fa1-4a97-5c04-99a8-8ac1d508b952'::uuid) group by 1 having count(*) > 25) s;
  if v_bad > 0 then raise exception 'Уроків з > 25 словами: %', v_bad; end if;
  select count(*) into v_bad from public.grammar_rules r join public.grammar_topics g on g.id = r.topic_id
   where g.cefr in ('A0', 'A1') and g.status = 'PUBLISHED'
     and (length(r.explanation_ua) < 150 or jsonb_array_length(coalesce(r.examples, '[]'::jsonb)) < 4);
  if v_bad > 0 then raise exception 'Правил A0 / A1 з коротким поясненням або < 4 прикладами: %', v_bad; end if;
  select count(*) into v_bad from public.lexemes l
    join (select li.item_id, min(le.level_code) lv from public.lesson_items li
            join public.lessons le on le.id = li.lesson_id and le.status = 'PUBLISHED' and le.level_code in ('A0', 'A1')
           where li.item_type = 'lexeme' group by li.item_id) f on f.item_id = l.id
   where l.cefr is distinct from f.lv;
  if v_bad > 0 then raise exception 'Слів, у яких cefr ≠ рівень уроку: %', v_bad; end if;
  raise notice 'Готово: 34 базові слова в уроках, правила A0 / A1 — ≥ 150 знаків і ≥ 4 приклади, cefr = рівень уроку';
end $$;

